import type { BeerStyleId } from './types';

/** Uno stile BJCP 2021, con i dati vitali ufficiali. */
export interface BjcpStyle {
  /** Chiave unica e slug nell'URL, es. "3B" oppure "27-kellerbier". */
  id: string;
  /** Etichetta ufficiale: "3B", "27" per gli stili storici. */
  code: string;
  name: string;
  categoryId: string;
  category: string;
  /** Famiglia larga, allineata a quelle dell'archivio. */
  family: string;
  /** Colore SRM al centro dell'intervallo ufficiale. */
  srm: number | null;
  /** Intervallo SRM ufficiale [min, max]. */
  color: [number, number] | null;
  /** [min, max] in % vol, o null quando lo stile non lo dichiara. */
  abv: [number, number] | null;
  /** [min, max] IBU, o null quando lo stile non lo dichiara. */
  ibu: [number, number] | null;
  og: [number, number] | null;
  fg: [number, number] | null;
  /** Rilettura italiana: cosa definisce lo stile e cosa lo distingue. */
  blurb: string;
  /** Testo ufficiale BJCP 2021 (inglese), sezione per sezione. */
  aroma: string | null;
  appearance: string | null;
  flavor: string | null;
  mouthfeel: string | null;
  comments: string | null;
  history: string | null;
  comparison: string | null;
  ingredients: string | null;
}

