export const BJCP_BY_ID: Map<string, BjcpStyle> = new Map(BJCP_STYLES.map((s) => [s.id, s]));

/** Le categorie BJCP in ordine ufficiale, con i loro stili. */
export const BJCP_CATEGORIES: { id: string; name: string; styles: BjcpStyle[] }[] = (() => {
  const out: { id: string; name: string; styles: BjcpStyle[] }[] = [];
  for (const s of BJCP_STYLES) {
    let c = out.find((x) => x.id === s.categoryId && x.name === s.category);
    if (!c) { c = { id: s.categoryId, name: s.category, styles: [] }; out.push(c); }
    c.styles.push(s);
  }
  return out;
})();

/** Ponte fra gli stili dell'archivio (approfondimenti) e il catalogo BJCP. */
export const APP_TO_BJCP: Partial<Record<BeerStyleId, string[]>> = {
  'pilsner': ["3B"],
  'helles': ["4A"],
  'marzen': ["6A"],
  'bock': ["6C"],
  'doppelbock': ["9A"],
  'weizenbock': ["10C"],
  'hefeweizen': ["10A"],
  'witbier': ["24A"],
  'saison': ["25B"],
  'berliner': ["23A"],
  'lambic': ["23D"],
  'gueuze': ["23E"],
  'pale-ale': ["18B", "12A"],
  'bitter': ["11A", "11B", "11C"],
  'amber': ["19A"],
  'ipa': ["21A", "12C"],
  'neipa': ["21C"],
  'dipa': ["22A"],
  'porter': ["13C", "20A"],
  'stout': ["15B"],
  'imperial-stout': ["20C"],
  'strong-golden': ["25C"],
  'dubbel': ["26B"],
  'tripel': ["26C"],
  'quadrupel': ["26D"],
  'rauchbier': ["6B"],
  'barleywine': ["17D", "22C"],
};

/** Inverso: da codice BJCP agli stili dell'archivio che lo incarnano. */
export const BJCP_TO_APP: Map<string, BeerStyleId[]> = (() => {
  const out = new Map<string, BeerStyleId[]>();
  for (const [app, codes] of Object.entries(APP_TO_BJCP) as [BeerStyleId, string[]][]) {
    for (const c of codes) {
      const arr = out.get(c);
      if (arr) arr.push(app);
      else out.set(c, [app]);
    }
  }
  return out;
})();
